import torch


def run(x):
    return x.arccosh_()


def run_correctness(x):
    x.copy_(torch.arccosh(x.float()).to(x.dtype))
    return x


def gen_inputs(ctx, device):
    shape = tuple(ctx["x__shape"])
    dtype = getattr(torch, ctx["x__dtype"])
    inp = torch.randn(shape, dtype=dtype, device=device)
    # arccosh requires input >= 1
    inp = inp.abs() + 1.0
    return {"x": inp}
